BEGIN;
DO $$
DECLARE f uuid:=gen_random_uuid();c uuid:=gen_random_uuid();p uuid:=gen_random_uuid();s uuid:=gen_random_uuid();m uuid:=gen_random_uuid();u uuid:=gen_random_uuid();mu uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();msid uuid:=gen_random_uuid();t uuid:=gen_random_uuid();tc uuid:=gen_random_uuid();contact uuid:=gen_random_uuid();approval uuid:=gen_random_uuid();receipt uuid:=gen_random_uuid();payment uuid:=gen_random_uuid();d uuid;n integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(u),(mu);INSERT INTO auth.sessions(id,user_id) VALUES(sid,u),(msid,mu);
 INSERT INTO erp_private.firms(firm_id,firm_code,legal_name) VALUES(f,'PR9QA','Fictional procedure firm');
 INSERT INTO erp_private.staff_members(staff_id,auth_user_id,staff_identifier,login_id,full_name,category_code,employment_type,access_status,sessions_invalid_before) VALUES(s,u,'PR9-PREP','pr9.prep','Fictional procedure preparer','ASSISTANT','Permanent','Active',now()-interval '1 day'),(m,mu,'PR9-MGR','pr9.manager','Fictional procedure Manager','MANAGER','Permanent','Active',now()-interval '1 day');
 INSERT INTO erp_private.pilot_sessions(session_id,staff_id,expires_at) VALUES(sid,s,now()+interval '1 hour'),(msid,m,now()+interval '1 hour');
 INSERT INTO erp_private.staff_firm_access(staff_id,firm_id) VALUES(s,f),(m,f);
 INSERT INTO erp_private.clients(client_id,company_name,owner_staff_id) VALUES(c,'Fictional procedure client',m);INSERT INTO erp_private.client_firm_links(client_id,firm_id) VALUES(c,f);
 INSERT INTO erp_private.projects(project_id,client_id,handling_firm_id,project_name,service_code,owner_staff_id) VALUES(p,c,f,'Fictional procedure project','TAX-COMP',m);
 INSERT INTO erp_private.project_assignments(project_id,staff_id,handling_firm_id,role_on_job) VALUES(p,s,f,'ASSISTANT'),(p,m,f,'MANAGER');
 INSERT INTO erp_private.tasks(task_id,project_id,assigned_to,task_name,template_key,period_start,period_end) VALUES(t,p,s,'Fictional VAT filing','monthly-vat','2026-09-01','2026-09-30');
 IF NOT EXISTS(SELECT 1 FROM erp_private.task_procedures WHERE task_id=t AND profile='Tax filing') THEN RAISE EXCEPTION 'Task procedure not generated';END IF;
 INSERT INTO erp_private.tax_cases(case_id,project_id,kind,starts_on,ends_on,prepared_by,reviewed_by,reviewed_at,review_snapshot,status) VALUES(tc,p,'VAT','2026-09-01','2026-09-30',s,m,now(),'{}','Locked');
 INSERT INTO erp_private.client_contacts(contact_id,client_id,full_name,job_title,role_in_decision) VALUES(contact,c,'Fictional representative','Finance Director','Decision Maker');
 FOREACH d IN ARRAY ARRAY[approval,receipt,payment] LOOP INSERT INTO erp_private.documents(document_id,client_id,handling_firm_id,project_id,task_id,category,file_name,object_key,file_size_bytes,sha256,mime_type,uploaded_by,is_locked) VALUES(d,c,f,p,t,'Working Papers','Fictional.pdf','qa/'||d,100,repeat('a',64),'application/pdf',s,true);END LOOP;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',u,'session_id',sid)::text,true);SET LOCAL ROLE erp_api;
 BEGIN UPDATE erp_private.tax_cases SET status='Filed',filing_date=current_date WHERE case_id=tc;RAISE EXCEPTION 'Unapproved filing passed';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE erp_private.tasks SET status='Completed',filing_date=current_date WHERE task_id=t;RAISE EXCEPTION 'Completed bypass passed';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE erp_private.task_procedures SET profile='Supporting task' WHERE task_id=t;RAISE EXCEPTION 'Filing gates weakened';EXCEPTION WHEN check_violation THEN NULL;END;
 UPDATE erp_private.task_procedures SET case_id=tc,reviewer_id=m,contact_id=contact,details='{"protocol":"Secure email","authority_reference":"Fictional EL section 11"}' WHERE task_id=t;
 BEGIN UPDATE erp_private.task_procedures SET stage='Ready to file' WHERE task_id=t;RAISE EXCEPTION 'Missing written approval passed';EXCEPTION WHEN check_violation THEN NULL;END;
 UPDATE erp_private.task_procedures SET approval_document_id=approval,details=details||'{"approval":{"approved_on":"2026-10-24","note":"Fictional written consent"}}'::jsonb,stage='Ready to file' WHERE task_id=t;
 UPDATE erp_private.task_procedures SET filing_document_id=receipt WHERE task_id=t;
 UPDATE erp_private.tax_cases SET status='Filed',filing_date=current_date WHERE case_id=tc;
 UPDATE erp_private.task_procedures SET stage='Filed - pending payment' WHERE task_id=t;
 BEGIN UPDATE erp_private.task_procedures SET stage='Closed',closed_by=s,closed_at=now(),payment_document_id=payment WHERE task_id=t;RAISE EXCEPTION 'Preparer closed own filing';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 RESET ROLE;PERFORM set_config('request.jwt.claims',json_build_object('sub',mu,'session_id',msid)::text,true);SET LOCAL ROLE erp_api;
 UPDATE erp_private.task_procedures SET stage='Closed',closed_by=m,closed_at=now(),payment_document_id=payment WHERE task_id=t;
 UPDATE erp_private.tasks SET status='Completed',filing_date=current_date WHERE task_id=t;
 BEGIN UPDATE erp_private.tasks SET status='In Progress' WHERE task_id=t;RAISE EXCEPTION 'Closed task reopened';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE erp_private.documents SET file_name='overwrite.pdf' WHERE document_id=approval;RAISE EXCEPTION 'Approval overwritten';EXCEPTION WHEN check_violation OR insufficient_privilege THEN NULL;END;
 IF has_table_privilege('anon','erp_private.task_procedures','SELECT') OR has_table_privilege('authenticated','erp_private.procedure_events','INSERT') THEN RAISE EXCEPTION 'Procedure tables exposed';END IF;
 RESET ROLE;
 SELECT count(*) INTO n FROM erp_private.schedule_occurrences('Weekly','Tax Compilation','2026-10-26','2026-11-01','2026-10-26',ARRAY['VAT'],'2026-10-26T02:59:00+03:00');IF n<>0 THEN RAISE EXCEPTION 'Weekly tax tasks released before 03:00 EAT';END IF;
 SELECT count(*) INTO n FROM erp_private.schedule_occurrences('Weekly','Tax Compilation','2026-10-26','2026-11-01','2026-10-26',ARRAY['VAT'],'2026-10-26T03:00:00+03:00');IF n<>6 THEN RAISE EXCEPTION 'Weekly tax release missing at 03:00 EAT';END IF;
END;$$;
ROLLBACK;
